// Manually maintained, may need to be rewritten to work with auto-generated files.
import antlr4 from 'antlr4';

export default class PseudocodeLexer extends antlr4.Lexer {
  constructor(input: any);
  static readonly EOF: number;
  static readonly ARR: number;
  static readonly TO: number;
  static readonly LBRACK: number;
  static readonly RBRACK: number;
  static readonly FUN: number;
  static readonly FOR: number;
  static readonly IN: number;
  static readonly IF: number;
  static readonly RETURN: number;
  static readonly END: number;
  static readonly ID: number;
  static readonly INT: number;
  static readonly NEG_INT: number;
  static readonly EQ: number;
  static readonly EQEQ: number;
  static readonly LPAREN: number;
  static readonly RPAREN: number;
  static readonly COLON: number;
  static readonly COMMA: number;
  static readonly NL: number;
  static readonly WS: number;
}